) AS src(RegionCode, Name, ShortName, RegionType, ProvinceCode, SortOrder)
JOIN Dim_Regions tinh ON tinh.RegionCode = src.ProvinceCode AND tinh.LevelType = 1
WHERE NOT EXISTS (SELECT 1 FROM Dim_Regions WHERE RegionCode = src.RegionCode);
GO

-- ============================================================
-- VERIFY SAU KHI SEED
-- ============================================================
SELECT COUNT(*) AS SoXaSauKhiSeed FROM Dim_Regions WHERE LevelType = 2;
GO

SELECT RegionType, COUNT(*) AS SoLuong
FROM Dim_Regions WHERE LevelType = 2
GROUP BY RegionType ORDER BY RegionType;
GO

SELECT TOP 10 tinh.Name AS TenTinh, COUNT(xa.Id) AS SoXa
FROM Dim_Regions tinh
LEFT JOIN Dim_Regions xa ON xa.ParentId = tinh.Id AND xa.LevelType = 2
WHERE tinh.LevelType = 1
GROUP BY tinh.Id, tinh.Name ORDER BY SoXa DESC;
GO

PRINT N'HOAN TAT SEED DIM_REGIONS';
GO